async function FINISH() {
  let wrd = 0;
  await V_SCORE();
  for (;;) {
    tell("\nWould you like to restart from the beginning, restore a saved position, or end this session of the game?\n(Type RESTART, RESTORE, or QUIT):\n >");
    await read(g.P_INBUF, g.P_LEXV);
    wrd = get(g.P_LEXV, 1);
    if (wrd == W.RESTART) {
      await restart();
      tell(S(g.FAILED));
    } else if (wrd == W.RESTORE) {
      if (await restore()) {
        tell("Ok.\n");
      } else {
        tell(S(g.FAILED));
      }
    } else if (wrd == W.QUIT || wrd == W.Q) {
      await quit();
    }
  }
}

