async function PRINT_CONTENTS(obj) {
  let f = 0, n_ = 0, _1st$ = true, it$ = false, two$ = false;
  if (f = first(obj)) {
    for (;;) {
      n_ = next(f);
      if (_1st$) {
        _1st$ = false;
      } else {
        tell(", ");
        if (!n_) {
          tell("and ");
        }
      }
      tell("a ", D(f));
      if (!it$ && !two$) {
        it$ = f;
      } else {
        two$ = true;
        it$ = false;
      }
      f = n_;
      if (!f) {
        if (it$ && !two$) {
          g.P_IT_OBJECT = it$;
        }
        return true;
      }
    }
  } else {
    return false;
  }
}

async function PRINT_CONT(obj, v$ = false, level = 0) {
  let y = 0, _1st$ = 0, shit = 0, av = false, str = 0, pv$ = false, inv$ = false;
  if (!(y = first(obj))) {
    return true;
  } else if (loc(ADVENTURER) == INFLATED_BOAT) {
    av = loc(g.WINNER);
  }
  _1st$ = true;
  shit = true;
  if (g.WINNER == obj || g.WINNER == loc(obj)) {
    inv$ = true;
  } else {
    loop1: for (;;) {
      if (!y) {
        break loop1;
      } else if (y == av) {
        pv$ = true;
      } else if (y == g.WINNER) {
      } else if (!(hasFlag(y, INVISIBLE)) && !(hasFlag(y, TOUCHBIT)) && (str = getProp(y, P.FDESC))) {
        if (!(hasFlag(y, NDESCBIT))) {
          tell(S(str), "\n");
          shit = false;
        }
        if ((await SEE_INSIDE$(y)) && !(getProp(loc(y), P.DESCFCN)) && first(y)) {
          if (await PRINT_CONT(y, v$, 0)) {
            _1st$ = false;
          }
        }
      }
      y = next(y);
    }
  }
  y = first(obj);
  loop2: for (;;) {
    if (!y) {
      if (pv$ && av && first(av)) {
        level = level + 1;
        await PRINT_CONT(av, v$, level);
      }
      break loop2;
    } else if (y == av || y == ADVENTURER) {
    } else if (!(hasFlag(y, INVISIBLE)) && (inv$ || hasFlag(y, TOUCHBIT) || !(getProp(y, P.FDESC)))) {
      if (!(hasFlag(y, NDESCBIT))) {
        if (_1st$) {
          if (await FIRSTER(obj, level)) {
            if (level < 0) {
              level = 0;
            }
          }
          level = 1 + level;
          _1st$ = false;
        }
        if (level < 0) {
          level = 0;
        }
        await DESCRIBE_OBJECT(y, v$, level);
      } else if (first(y) && (await SEE_INSIDE$(y))) {
        level = level + 1;
        await PRINT_CONT(y, v$, level);
        level = level - 1;
      }
    }
    y = next(y);
  }
  if (_1st$ && shit) {
    return false;
  } else {
    return true;
  }
}

