async function CCOUNT(obj) {
  let cnt = 0, x = 0;
  if (x = first(obj)) {
    loop1: for (;;) {
      cnt = cnt + 1;
      if (!(x = next(x))) {
        break loop1;
      }
    }
  }
  return cnt;
}

async function WEIGHT(obj) {
  let cont = 0, wt = 0;
  if (cont = first(obj)) {
    loop1: for (;;) {
      wt = wt + (await WEIGHT(cont));
      if (!(cont = next(cont))) {
        break loop1;
      }
    }
  }
  return wt + getProp(obj, P.SIZE);
}

async function GOTO(rm, v$ = true) {
  let wloc = loc(g.WINNER), olit = 0, ohere = 0;
  olit = g.LIT;
  ohere = g.HERE;
  if (hasFlag(rm, NONLANDBIT) && !(loc(ADVENTURER) == INFLATED_BOAT)) {
    tell(S(g.YOU_CANT), "go there without a boat.\n");
    return false;
  } else if (hasFlag(rm, RLANDBIT) && hasFlag(g.HERE, RLANDBIT) && (loc(ADVENTURER) == INFLATED_BOAT)) {
    tell("You'll have to get out of the raft first.\n");
    return false;
  } else {
    if ((loc(ADVENTURER) == INFLATED_BOAT) && !(hasFlag(g.HERE, RLANDBIT)) && hasFlag(rm, RLANDBIT) && !g.DEAD) {
      tell("The ", D(wloc), " comes to a rest on the shore.\n\n");
    }
    if (loc(ADVENTURER) == INFLATED_BOAT) {
      move(wloc, rm);
    } else {
      move(g.WINNER, rm);
    }
    g.HERE = rm;
    g.LIT = await LIT$(g.HERE);
    if (!olit && !g.LIT && (80 > random(100))) {
      tell("Oh, no! A lurking grue slithered into the ");
      if (loc(ADVENTURER) == INFLATED_BOAT) {
        tell(D(loc(g.WINNER)));
      } else {
        tell("room");
      }
      (await JIGS_UP(" and devoured you!"));
      return true;
    }
    if (!g.LIT && (g.WINNER == ADVENTURER)) {
      tell("You have moved into a dark place.\n");
      g.P_CONT = false;
    }
    await apply(getProp(g.HERE, P.ACTION), M_ENTER);
    await SCORE_OBJ(rm);
    if (!(g.HERE == rm)) {
      return true;
    } else if ((g.HERE == ohere) && (g.HERE == ENTRANCE_TO_HADES)) {
      return true;
    } else if (v$ && (g.WINNER == ADVENTURER) && (await DESCRIBE_ROOM()) && (g.VERBOSITY > 0)) {
      await DESCRIBE_OBJECTS();
    }
    return true;
  }
}

