async function I_THIEF() {
  let x = 0, thief_loc = loc(THIEF), robj = 0, here$ = 0, once = false, flg = false;
  loop1: for (;;) {
    if (here$ = !(hasFlag(THIEF, INVISIBLE))) {
      thief_loc = loc(THIEF);
    }
    if ((thief_loc == THIEFS_LAIR) && !(thief_loc == g.HERE)) {
      await DEPOSIT_BOOTY(THIEFS_LAIR);
      if (here$) {
        setFlag(THIEF, INVISIBLE);
        x = first(THIEFS_LAIR);
        loop2: for (;;) {
          if (!x) {
            break loop2;
          } else {
            clearFlag(x, INVISIBLE);
          }
          x = next(x);
        }
        here$ = false;
      }
    } else if ((thief_loc == g.HERE) && !(hasFlag(thief_loc, ONBIT)) && !(loc(TROLL) == g.HERE)) {
      if (await THIEF_VS_ADVENTURER(here$)) {
        return true;
      }
      if (hasFlag(THIEF, INVISIBLE)) {
        here$ = false;
      }
    } else {
      if ((loc(THIEF) == thief_loc) && !(hasFlag(THIEF, INVISIBLE))) {
        setFlag(THIEF, INVISIBLE);
        here$ = false;
      }
      if (hasFlag(thief_loc, TOUCHBIT)) {
        await ROB(thief_loc, THIEF, true);
        flg = hasFlag(thief_loc, MAZEBIT) && hasFlag(g.HERE, MAZEBIT) ? (await ROB_MAZE(thief_loc)) : (await STEAL_JUNK(thief_loc));
      }
    }
    if ((once = !once) && !here$) {
      loop3: for (;;) {
        if (thief_loc && setVarIndirect(thief_loc, next(thief_loc))) {
        } else {
          thief_loc = first(ROOMS);
        }
        if (!(hasFlag(thief_loc, SACREDBIT)) && hasFlag(thief_loc, RLANDBIT)) {
          move(THIEF, thief_loc);
          setFlag(THIEF, INVISIBLE);
          g.THIEF_HERE = false;
          break loop3;
        }
      }
      continue loop1;
    }
    break loop1;
  }
  if (!(thief_loc == THIEFS_LAIR)) {
    await DROP_JUNK(thief_loc);
  }
  return flg;
}

async function DROP_JUNK(rm) {
  let x = 0, n_ = 0, flg = false;
  x = first(THIEF);
  for (;;) {
    if (!x) {
      return flg;
    }
    n_ = next(x);
    if (!(hasFlag(x, TREASUREBIT)) && !(x == STILETTO || x == LARGE_BAG) && (await ZPROB(30))) {
      clearFlag(x, INVISIBLE);
      move(x, rm);
      if (!flg && (rm == g.HERE)) {
        tell("The robber rummages through his bag and drops a few valueless items.\n");
        flg = true;
      }
    }
    x = n_;
  }
}

async function STEAL_JUNK(rm) {
  let x = 0, n_ = 0;
  x = first(rm);
  for (;;) {
    if (!x) {
      return false;
    }
    n_ = next(x);
    if (hasFlag(x, TREASUREBIT) && hasFlag(x, TAKEBIT) && !(hasFlag(x, SACREDBIT)) && !(hasFlag(x, INVISIBLE)) && (await ZPROB(10))) {
      move(x, THIEF);
      setFlag(x, TOUCHBIT);
      setFlag(x, INVISIBLE);
      if (x == ROPE) {
        g.DOME_FLAG = false;
      }
      if (rm == g.HERE) {
        tell("The ", D(x), " has vanished!\n");
        return true;
      } else {
        return false;
      }
    }
    x = n_;
  }
}

async function ROB(what, where, just_treasures) {
  let n_ = 0, x = 0, robbed = false;
  x = first(what);
  loop1: for (;;) {
    if (!x) {
      break loop1;
    }
    n_ = next(x);
    if (hasFlag(x, INVISIBLE)) {
    } else if (just_treasures && (hasFlag(x, SACREDBIT) || !(hasFlag(x, TREASUREBIT)))) {
    } else {
      move(x, where);
      setFlag(x, TOUCHBIT);
      robbed = true;
      if (where == THIEF) {
        setFlag(x, INVISIBLE);
      }
    }
    x = n_;
  }
  return robbed;
}

