async function HERO_BLOW() {
  let vil_str = 0, hit_prob = 0;
  vil_str = getProp(g.PRSO, P.STRENGTH);
  if (g.PRSO == TROLL) {
    hit_prob = 45;
  } else {
    hit_prob = 15 + div(g.SCORE, 4);
  }
  if (hit_prob > random(100)) {
    if (50 > random(100)) {
      vil_str = vil_str - 2;
      if (vil_str < 0) {
        await KILL_VILLAIN();
      } else if (50 > random(100)) {
        tell("The ", D(g.PRSO), " receives a deep gash in his side.\n");
      } else {
        tell("Slash! Your ", D(g.PRSI), " connects! This could be serious!\n");
      }
    } else {
      vil_str = vil_str - 1;
      if (vil_str < 0) {
        await KILL_VILLAIN();
      } else if (50 > random(100)) {
        tell("The ", D(g.PRSO), " is struck on the arm; blood begins to trickle down.\n");
      } else {
        tell("The blow lands, making a shallow gash in the ", D(g.PRSO), "'s arm!\n");
      }
    }
    return putProp(g.PRSO, P.STRENGTH, vil_str);
  } else if (50 > random(100)) {
    tell("A good slash, but it misses the ", D(g.PRSO), " by a mile.\n");
    return true;
  } else {
    tell("You charge, but the ", D(g.PRSO), " jumps nimbly aside.\n");
    return true;
  }
}

async function KILL_VILLAIN() {
  let x = 0;
  tell("The fatal blow strikes the ", D(g.PRSO), " square in the heart: He dies. As the ", D(g.PRSO), " breathes his last breath, a cloud of sinister black fog envelops him; when it lifts, the carcass is gone.\n");
  remove(g.PRSO);
  if (g.PRSO == TROLL) {
    putProp(TROLL, P.STRENGTH, 2);
    move(AXE, g.HERE);
    clearFlag(AXE, NDESCBIT);
    setFlag(AXE, WEAPONBIT);
    setFlag(AXE, TAKEBIT);
    g.TROLL_FLAG = true;
    return g.SCORE = g.SCORE + 10;
  } else {
    putProp(THIEF, P.STRENGTH, 5);
    move(STILETTO, g.HERE);
    clearFlag(STILETTO, NDESCBIT);
    setFlag(STILETTO, TAKEBIT);
    setFlag(STILETTO, WEAPONBIT);
    disable(await INT(I_THIEF.id));
    if (await DEPOSIT_BOOTY(g.HERE)) {
      if (g.HERE == THIEFS_LAIR) {
        tell("As the thief dies, his treasures reappear.");
      } else {
        tell("His booty remains.");
      }
      crlf();
      crlf();
      return await V_LOOK();
    } else {
      return false;
    }
  }
}

async function I_FIGHT() {
  let adv_str = 0, tbl = 0, hit_prob = 0;
  enable(await QUEUE(I_FIGHT.id, -1));
  adv_str = getProp(ADVENTURER, P.STRENGTH);
  if (loc(TROLL) == g.HERE) {
    hit_prob = 55;
    tbl = g.TROLL_MELEE;
  } else if (loc(THIEF) == g.HERE) {
    hit_prob = 60;
    tbl = g.THIEF_MELEE;
  } else {
    disable(await INT(I_FIGHT.id));
    enable(await QUEUE(I_CURE.id, -1));
    return false;
  }
  if (hit_prob > random(100)) {
    if (50 > random(100)) {
      adv_str = adv_str - 2;
      if (adv_str < 0) {
        await JIGS_UP(get(tbl, 6));
      } else if (50 > random(100)) {
        tell(S(get(tbl, 5)), "\n");
      } else {
        tell(S(get(tbl, 4)), "\n");
      }
    } else {
      adv_str = adv_str - 1;
      if (adv_str < 0) {
        await JIGS_UP(get(tbl, 6));
      } else if (50 > random(100)) {
        tell(S(get(tbl, 3)), "\n");
      } else {
        tell(S(get(tbl, 2)), "\n");
      }
    }
    return putProp(ADVENTURER, P.STRENGTH, adv_str);
  } else if (50 > random(100)) {
    tell(S(get(tbl, 1)), "\n");
    return true;
  } else {
    tell(S(get(tbl, 0)), "\n");
    return true;
  }
}

async function I_CURE() {
  let adv_str = 0, troll_str = 0, thief_str = 0;
  adv_str = getProp(ADVENTURER, P.STRENGTH);
  troll_str = getProp(TROLL, P.STRENGTH);
  thief_str = getProp(THIEF, P.STRENGTH);
  if ((adv_str == 6) && (troll_str == 2) && (thief_str == 5)) {
    disable(await INT(I_CURE.id));
    g.CURE_COUNT = 10;
    return false;
  }
  g.CURE_COUNT = g.CURE_COUNT - 1;
  if (g.CURE_COUNT == 0) {
    if (adv_str < 6) {
      putProp(ADVENTURER, P.STRENGTH, adv_str + 1);
    }
    if (troll_str < 2) {
      putProp(TROLL, P.STRENGTH, troll_str + 1);
    }
    if (thief_str < 5) {
      putProp(THIEF, P.STRENGTH, thief_str + 1);
    }
    g.CURE_COUNT = 10;
  }
  return false;
}

