async function COUNT_TREASURES(obj) {
  let x = first(obj), cnt = 0;
  loop1: for (;;) {
    if (!x) {
      break loop1;
    }
    if (hasFlag(x, TREASUREBIT)) {
      cnt = cnt + 1;
    }
    cnt = cnt + (await COUNT_TREASURES(x));
    x = next(x);
  }
  return cnt;
}

