async function INFLATED_BOAT_F(rarg = false) {
  let tmp = 0;
  if (rarg == M_BEG) {
    if (isVerb(V.WALK)) {
      if ((g.HERE == RIVER_1 || g.HERE == RIVER_2 || g.HERE == RIVER_3) && (g.PRSO == P.LAND || g.PRSO == P.EAST || g.PRSO == P.WEST || g.PRSO == P.UP || g.PRSO == P.DOWN)) {
        return false;
      } else if ((g.HERE == RESERVOIR) && (g.PRSO == P.NORTH || g.PRSO == P.SOUTH)) {
        return false;
      } else {
        tell("Read the tan label!\n");
        return true;
      }
    } else if (isVerb(V.LAUNCH)) {
      if ((g.HERE == RIVER_1 || g.HERE == RIVER_2 || g.HERE == RIVER_3) || (g.HERE == RESERVOIR)) {
        tell(S(g.ALREADY));
        return true;
      } else if (eq(tmp = await GO_NEXT(g.RIVER_LAUNCH), 1)) {
        enable(await QUEUE(I_RIVER.id, await LKP(g.HERE, g.RIVER_SPEEDS)));
        return true;
      } else if (!(tmp == 2)) {
        tell(S(g.YOU_CANT), "launch it here.\n");
        return true;
      } else {
        return true;
      }
    } else {
      return false;
    }
  } else if (rarg) {
    return false;
  } else if (isVerb(V.INFLATE, V.FILL)) {
    tell("Inflating it further might burst it.\n");
    return true;
  } else if (isVerb(V.DEFLATE)) {
    if (loc(ADVENTURER) == INFLATED_BOAT) {
      tell("You're in it!\n");
      return true;
    } else if (!(loc(INFLATED_BOAT) == g.HERE)) {
      return (await MUST_BE_ON_GROUND("de"));
    } else {
      move(INFLATABLE_BOAT, g.HERE);
      g.P_IT_OBJECT = INFLATABLE_BOAT;
      tell("The boat deflates.\n");
      return await REMOVE_CAREFULLY(INFLATED_BOAT);
    }
  } else if (isVerb(V.CLIMB_ON)) {
    await PERFORM(V.BOARD, g.PRSO);
    return true;
  } else {
    return false;
  }
}

