async function ENTRANCE_TO_HADES_F(rarg) {
  if (rarg == M_LOOK) {
    tell("You are outside a large gate inscribed, \"Abandon hope all ye who enter here!\" The gate is open; beyond you can see a desolation, with a pile of mangled bodies in one corner. Thousands of voices, lamenting some hideous fate, can be heard.");
    if (!g.HADES_FLAG && !g.DEAD) {
      tell(" The gate is barred by evil spirits, who jeer at your attempts to pass.");
      return true;
    } else {
      return false;
    }
  } else if (rarg == M_BEG) {
    if (isVerb(V.EXORCISE)) {
      if (g.HADES_FLAG) {
        tell(S(g.ALREADY), "\n");
        return true;
      } else if ((await HELD$(BELL)) && (await HELD$(BLACK_BOOK)) && (await HELD$(CANDLES))) {
        tell(S(g.PERFORM_CEREMONY));
        return true;
      } else {
        tell("You're not equipped for an exorcism.\n");
        return true;
      }
    } else if (!g.HADES_FLAG && isVerb(V.RING) && (g.PRSO == BELL)) {
      g.XB = true;
      enable(await QUEUE(I_XB.id, 6));
      tell("A deep peal issues from the bell. The wraiths stop jeering and an expression of long-forgotten terror takes shape on their ashen faces.");
      if (loc(CANDLES) == g.WINNER) {
        move(CANDLES, g.HERE);
        clearFlag(CANDLES, ONBIT);
        disable(await INT(I_CANDLES.id));
        tell(" In your confusion, the candles drop to the ground (and they are out).");
      }
      return crlf();
    } else if (g.XC && isVerb(V.READ) && (g.PRSO == BLACK_BOOK) && !g.HADES_FLAG) {
      remove(GHOSTS);
      g.HADES_FLAG = true;
      disable(await INT(I_XC.id));
      tell("The prayer reverberates in a deafening confusion. As the last word fades, a heart-stopping scream fills the cavern, and the spirits, sensing a greater power, flee through the walls.\n");
      return true;
    } else {
      return false;
    }
  } else if (rarg == M_END) {
    if (g.XB && (loc(CANDLES) == g.WINNER) && hasFlag(CANDLES, ONBIT) && !g.XC) {
      g.XC = true;
      disable(await INT(I_XB.id));
      enable(await QUEUE(I_XC.id, 3));
      tell("The flames flicker wildly and the earth trembles beneath your feet. The spirits cower at your unearthly power.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

