async function GO_NEXT(tbl) {
  let val = 0;
  if (val = await LKP(g.HERE, tbl)) {
    if (!(await GOTO(val))) {
      return 2;
    } else {
      return 1;
    }
  } else {
    return false;
  }
}

async function LKP(itm, tbl) {
  let cnt = 0, len = get(tbl, 0);
  for (;;) {
    if ((cnt = cnt + 1) > len) {
      return false;
    } else if (eq(get(tbl, cnt), itm)) {
      if (cnt == len) {
        return false;
      } else {
        return get(tbl, cnt + 1);
      }
    }
  }
}

