async function BASKET_F() {
  if (isVerb(V.MOVE)) {
    await PERFORM(g.BASKET_RAISED ? V.LOWER : V.RAISE, BASKET);
    return true;
  } else if (isVerb(V.RAISE)) {
    if (g.BASKET_RAISED) {
      tell(S(g.LOOK_AROUND));
      return true;
    } else {
      move(BASKET, SHAFT_ROOM);
      g.BASKET_RAISED = true;
      tell("The basket is raised to the top of the shaft.\n");
      return await NOW_DARK$();
    }
  } else if (isVerb(V.LOWER)) {
    if (!g.BASKET_RAISED) {
      tell(S(g.LOOK_AROUND));
      return true;
    } else {
      move(BASKET, DRAFTY_ROOM);
      g.BASKET_RAISED = false;
      tell("The basket is lowered to the bottom of the shaft.\n");
      return await NOW_DARK$();
    }
  } else if (isVerb(V.TAKE) && (g.PRSO == BASKET)) {
    return (await FASTENED(BASKET, "chain"));
  } else {
    return false;
  }
}

async function CHAIN_PSEUDO() {
  if (isVerb(V.TAKE)) {
    tell("The chain is secure.\n");
    return true;
  } else if (isVerb(V.RAISE, V.LOWER, V.MOVE)) {
    await PERFORM(g.PRSA, BASKET);
    return true;
  } else if (isVerb(V.EXAMINE) && (loc(BASKET) == g.HERE)) {
    tell(S(getProp(BASKET, P.LDESC)), "\n");
    return true;
  } else {
    return false;
  }
}

async function GAS_ROOM_F(rarg) {
  if (rarg == M_END) {
    if (((await HELD$(CANDLES)) && hasFlag(CANDLES, ONBIT)) || ((await HELD$(TORCH)) && hasFlag(TORCH, ONBIT)) || ((await HELD$(MATCH)) && hasFlag(MATCH, ONBIT))) {
      return (await JIGS_UP("Oh dear. That smell was coal gas. I would have thought twice about carrying flaming objects in here.\n\nBooooooom!!!"));
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function GAS_PSEUDO() {
  if (isVerb(V.BREATHE)) {
    tell("There is too much gas to blow away.\n");
    return true;
  } else if (isVerb(V.SMELL)) {
    tell("It smells like coal gas in here.\n");
    return true;
  } else {
    return false;
  }
}

async function LADDER_PSEUDO() {
  if (isVerb(V.CLIMB)) {
    return await DO_WALK(P.UP);
  } else {
    return false;
  }
}

async function NO_OBJECT_ROOM_F(rarg) {
  let f = 0;
  if (rarg == M_BEG) {
    f = first(g.WINNER);
    g.EMPTY_HANDED = true;
    loop1: for (;;) {
      if (!f) {
        break loop1;
      } else if ((await WEIGHT(f)) > 4) {
        g.EMPTY_HANDED = false;
        break loop1;
      }
      f = next(f);
    }
    if ((g.HERE == DRAFTY_ROOM) && g.LIT && !g.DRAFTY_ROOM_SCORE) {
      g.DRAFTY_ROOM_SCORE = true;
      g.SCORE = g.SCORE + 10;
    }
    return false;
  } else {
    return false;
  }
}

async function MACHINE_ROOM_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a chilly room whose sole exit is to the north. In one corner is a machine, reminiscent of a clothes dryer, with a switch labelled \"START\". The switch does not appear to be manipulable by any human hand (unless the fingers are about 1/16 by 1/4 inch). The machine has a large lid, which is ");
    if (hasFlag(MACHINE, OPENBIT)) {
      tell("open.");
      return true;
    } else {
      tell("closed.");
      return true;
    }
  } else {
    return false;
  }
}

async function MACHINE_F() {
  if (isVerb(V.LAMP_ON)) {
    if (!g.PRSI) {
      tell(S(g.YOU_CANT), "do it with your bare hands.\n");
      return true;
    } else {
      await PERFORM(V.TURN, MACHINE_SWITCH, g.PRSI);
      return true;
    }
  } else {
    return false;
  }
}

async function MACHINE_SWITCH_F() {
  let slag$ = 0;
  if (isVerb(V.TURN)) {
    if (g.PRSI == SCREWDRIVER) {
      if (hasFlag(MACHINE, OPENBIT)) {
        tell(S(g.NOTHING_HAPPENS));
        return true;
      } else {
        slag$ = first(MACHINE);
        await ROB(MACHINE, MACHINE_SWITCH, false);
        if (loc(COAL) == MACHINE_SWITCH) {
          move(DIAMOND, MACHINE);
        } else if (slag$) {
          move(SLAG, MACHINE);
        }
        tell("The machine produces a dazzling display of colored lights and bizarre noises. A moment later, the excitement abates.\n");
        return true;
      }
    } else {
      tell("It seems that a ", D(g.PRSI), " won't do.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function SLAG_F() {
  remove(SLAG);
  tell("The insubstantial slag crumbles at your touch.\n");
  return true;
}

async function BAG_OF_COINS_F() {
  return (await STUPID_CONTAINER(BAG_OF_COINS, "coins"));
}

async function RUSTY_KNIFE_F() {
  if (isVerb(V.TAKE) && (loc(SWORD) == g.WINNER)) {
    tell("As you touch the rusty knife, your sword gives a single pulse of blinding blue light.\n");
    return false;
  } else if (((g.PRSI == RUSTY_KNIFE) && isVerb(V.ATTACK)) || (isVerb(V.SWING) && (g.PRSO == RUSTY_KNIFE) && g.PRSI)) {
    remove(RUSTY_KNIFE);
    return (await JIGS_UP("The knife, moving with its own force, slowly turns your hand, until the blade is at your neck. The knife seems to sing as it savagely slits your throat."));
  } else {
    return false;
  }
}

async function SKELETON_F() {
  if (isVerb(V.TAKE, V.RUB, V.MOVE, V.PUSH, V.RAISE, V.LOWER, V.ATTACK, V.KICK, V.KISS)) {
    await ROB(g.HERE, HADES, true);
    await ROB(ADVENTURER, HADES, true);
    tell("A ghost appears, appalled at your desecration of the remains of a fellow adventurer. He curses your valuables and banishes them to Hades. The ghost leaves, muttering obscenities.\n");
    return true;
  } else {
    return false;
  }
}

async function GRATING_ROOM_F(rarg) {
  if (rarg == M_ENTER) {
    return clearFlag(GRATE, INVISIBLE);
  } else if (rarg == M_LOOK) {
    tell("You are in a room off the maze, which lies to the southwest. Above you is a");
    if (hasFlag(GRATE, OPENBIT)) {
      tell("n open grating with sunlight pouring in.");
      return true;
    } else if (g.GRUNLOCK) {
      tell(" grating.");
      return true;
    } else {
      tell(" grating locked with a skull-and-crossbones lock.");
      return true;
    }
  } else {
    return false;
  }
}

async function GRATE_F() {
  if (isVerb(V.OPEN) && (g.PRSI == KEYS)) {
    await PERFORM(V.UNLOCK, GRATE, KEYS);
    return true;
  } else if (isVerb(V.LOCK, V.UNLOCK) && (g.HERE == FOREST_PATH)) {
    tell(S(g.YOU_CANT), "from this side.\n");
    return true;
  } else if (isVerb(V.LOCK)) {
    g.GRUNLOCK = false;
    tell("Locked.\n");
    return true;
  } else if (isVerb(V.UNLOCK) && (g.PRSO == GRATE)) {
    if (g.PRSI == KEYS) {
      g.GRUNLOCK = true;
      tell("Unlocked.\n");
      return true;
    } else {
      tell("With a ", D(g.PRSI), "!?!\n");
      return true;
    }
  } else if (isVerb(V.PICK)) {
    tell("You haven't the skill.\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    if (g.GRUNLOCK) {
      (await OPEN_CLOSE(GRATE, "The grating opens.", "The grating closes."));
      if (hasFlag(GRATE, OPENBIT)) {
        setFlag(GRATING_ROOM, ONBIT);
        if (!(g.HERE == FOREST_PATH) && !g.GRATE_REVEALED) {
          g.GRATE_REVEALED = true;
          move(LEAVES, g.HERE);
          tell("A pile of leaves falls onto your head and to the ground.\n");
        }
      } else {
        clearFlag(GRATING_ROOM, ONBIT);
      }
      return true;
    } else {
      tell("The grating is locked.\n");
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == GRATE)) {
    tell("It won't fit through the grating.\n");
    return true;
  } else {
    return false;
  }
}

async function CYCLOPS_ROOM_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This room has a northwest exit and a staircase leading up. ");
    return await D_CYCLOPS();
  } else if (rarg == M_ENTER) {
    return (g.CYCLOWRATH == 0) || enable(await INT(I_CYCLOPS.id));
  } else {
    return false;
  }
}

async function CYCLOPS_F() {
  if (g.WINNER == CYCLOPS) {
    if (g.CYCLOPS_FLAG) {
      tell("He's fast asleep.\n");
      return true;
    } else if (isVerb(V.ODYSSEUS)) {
      g.WINNER = ADVENTURER;
      await PERFORM(V.ODYSSEUS);
      return true;
    } else {
      tell("He's not much of a conversationalist.\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    await D_CYCLOPS();
    return crlf();
  } else if (g.CYCLOPS_FLAG) {
    if (isVerb(V.ALARM, V.KICK, V.ATTACK, V.BURN, V.MUNG) || (isVerb(V.TIE_UP) && (g.PRSI == ROPE))) {
      tell("The cyclops yawns and stares at the thing that woke him up.\n");
      g.CYCLOPS_FLAG = false;
      if (g.CYCLOWRATH < 0) {
        return g.CYCLOWRATH = -g.CYCLOWRATH;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.GIVE) && (g.PRSI == CYCLOPS)) {
    if (g.PRSO == LUNCH) {
      enable(await QUEUE(I_CYCLOPS.id, -1));
      if (g.CYCLOWRATH > (-1)) {
        remove(LUNCH);
        g.CYCLOWRATH = (-1) < (-g.CYCLOWRATH) ? (-1) : (-g.CYCLOWRATH);
        tell("The cyclops says, \"Yum, that made me thirsty. Perhaps I could drink the blood of that thing.\" It appears that YOU are \"that thing.\"\n");
        return true;
      } else {
        return false;
      }
    } else if ((g.PRSO == WATER) || ((g.PRSO == BOTTLE) && (loc(WATER) == BOTTLE))) {
      if (g.CYCLOWRATH < 0) {
        await REMOVE_CAREFULLY(WATER);
        move(BOTTLE, g.HERE);
        setFlag(BOTTLE, OPENBIT);
        g.CYCLOPS_FLAG = true;
        tell("The cyclops empties the bottle, yawns, and falls fast asleep. (What did you put in that drink, anyway?)\n");
        return true;
      } else {
        tell(S(g.CYCLOPS_IS), "n't thirsty and refuses your offer.\n");
        return true;
      }
    } else if (g.PRSO == GARLIC) {
      tell(S(g.CYCLOPS_IS), "n't THAT hungry.\n");
      return true;
    } else {
      tell("The cyclops won't eat THAT!\n");
      return true;
    }
  } else if (isVerb(V.THROW, V.ATTACK, V.MUNG)) {
    enable(await QUEUE(I_CYCLOPS.id, -1));
    if (isVerb(V.MUNG)) {
      tell("\"Do you think I'm as stupid as my father was?\", he says, dodging.\n");
      return true;
    } else {
      if (isVerb(V.THROW)) {
        move(g.PRSO, g.HERE);
      }
      tell("The cyclops ignores your pitiful attempt.\n");
      return true;
    }
  } else if (isVerb(V.TIE)) {
    tell("You cannot tie him, though he is fit to be tied.\n");
    return true;
  } else if (isVerb(V.LISTEN)) {
    tell("You can hear his stomach rumbling.\n");
    return true;
  } else {
    return false;
  }
}

async function D_CYCLOPS() {
  if (g.MAGIC_FLAG) {
    tell("The east wall has a cyclops-sized opening in it.");
    return true;
  } else if (g.CYCLOPS_FLAG) {
    tell("The cyclops sleeps blissfully at the foot of the stairs.");
    return true;
  } else if (g.CYCLOWRATH == 0) {
    tell("A hungry cyclops blocks the staircase. From the bloodstains on the walls, you gather that he is not very friendly, though he likes people.");
    return true;
  } else if (g.CYCLOWRATH > 0) {
    tell(S(g.CYCLOPS_IS), " eyeing you closely. I don't think he likes you very much. He looks extremely hungry, even for a cyclops.");
    return true;
  } else if (g.CYCLOWRATH < 0) {
    tell("The cyclops, having eaten the hot peppers, appears to be gasping. His enflamed tongue protrudes from his man-sized mouth.");
    return true;
  } else {
    return false;
  }
}

async function I_CYCLOPS() {
  if (g.CYCLOPS_FLAG || g.DEAD) {
    return true;
  } else if (!(g.HERE == CYCLOPS_ROOM)) {
    return disable(await INT(I_CYCLOPS.id));
  } else if (Math.abs(g.CYCLOWRATH) > 5) {
    disable(await INT(I_CYCLOPS.id));
    return (await JIGS_UP("The cyclops, tired of your trickery, grabs you firmly. \"Mmm. Just like Mom used to make 'em.\""));
  } else {
    if (g.CYCLOWRATH < 0) {
      g.CYCLOWRATH = g.CYCLOWRATH - 1;
    } else {
      g.CYCLOWRATH = g.CYCLOWRATH + 1;
    }
    if (!g.CYCLOPS_FLAG) {
      tell(S(g.CYCLOPS_IS), S(get(g.CYCLOMAD, Math.abs(g.CYCLOWRATH) - 1)), "\n");
      return true;
    } else {
      return false;
    }
  }
}

async function THIEFS_LAIR_F(rarg) {
  if ((rarg == M_ENTER) && (get(await INT(I_THIEF.id), C_ENABLED$) == 1) && !g.DEAD) {
    clearFlag(THIEF, INVISIBLE);
    if (!(loc(THIEF) == g.HERE)) {
      move(THIEF, g.HERE);
      enable(await QUEUE(I_FIGHT.id, -1));
      tell("You hear a scream of anguish as the robber rushes to defend his hideaway.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CHALICE_F() {
  if (isVerb(V.OPEN, V.CLOSE)) {
    tell("Huh?\n");
    return true;
  } else {
    return false;
  }
}

